-- Arbeitsrecht Berufsbildung > Soziale gesellschaftliche Themen > Arbeitsschutz > Unfallverhütung
INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Ist die Unfallverhütung in einem IT-Betrieb gesetzlich vorgeschrieben?', 2, '[{"text": "Ja", "correct": true, "because": "ArbSchG und DGUV-Vorschriften verpflichten zur Unfallverhütung"}, {"text": "Nein", "correct": false, "because": "Gesetzlich geregelt"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann eine gute Unfallverhütung in einem IT-Betrieb Stolperfallen durch Kabel vermeiden?', 2, '[{"text": "Ja", "correct": true, "because": "Kabelmanagement reduziert Stolperrisiken"}, {"text": "Nein", "correct": false, "because": "Prävention wirkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Müssen Fachinformatiker bei der Unfallverhütung elektrische Gefahren berücksichtigen?', 2, '[{"text": "Ja", "correct": true, "because": "Arbeit mit Hardware birgt Stromrisiken"}, {"text": "Nein", "correct": false, "because": "Elektrische Sicherheit ist relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Unfallverhütung in einem IT-Betrieb nur für physische Arbeitsplätze relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Homeoffice und Serverräume betroffen"}, {"text": "Ja", "correct": false, "because": "Umfassend geregelt"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann die Unfallverhütung die Produktivität eines IT-Betriebs steigern?', 2, '[{"text": "Ja", "correct": true, "because": "Weniger Ausfälle durch Unfälle"}, {"text": "Nein", "correct": false, "because": "Produktivität wird gefördert"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welches Gesetz regelt die Unfallverhütung in einem IT-Betrieb?', 2, '[{"text": "Arbeitsschutzgesetz (ArbSchG)", "correct": true, "because": "ArbSchG ist die Grundlage"}, {"text": "BBiG", "correct": false, "because": "Regelt Ausbildung"}, {"text": "HGB", "correct": false, "because": "Regelt Handel"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist das Hauptziel der Unfallverhütung in einem IT-Betrieb?', 3, '[{"text": "Schutz der Mitarbeiter vor Unfällen", "correct": true, "because": "ArbSchG § 3 fordert Sicherheit"}, {"text": "Erhöhung der Arbeitszeit", "correct": false, "because": "Kein Ziel"}, {"text": "Kostensteigerung", "correct": false, "because": "Nicht beabsichtigt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahme der Unfallverhütung ist für Fachinformatiker besonders wichtig?', 3, '[{"text": "Sicheres Kabelmanagement", "correct": true, "because": "Verhindert Stolperfallen bei IT-Arbeitsplätzen"}, {"text": "Lärmschutz", "correct": false, "because": "Weniger relevant"}, {"text": "Höhere Decken", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Wer ist für die Umsetzung der Unfallverhütung in einem IT-Betrieb verantwortlich?', 2, '[{"text": "Der Arbeitgeber", "correct": true, "because": "ArbSchG legt Verantwortung beim Arbeitgeber"}, {"text": "Die Mitarbeiter", "correct": false, "because": "Mitarbeiter unterstützen nur"}, {"text": "Die Gewerkschaft", "correct": false, "because": "Keine direkte Rolle"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Nachteil kann durch Unfallverhütung in einem IT-Betrieb entstehen?', 3, '[{"text": "Kosten für Sicherheitsmaßnahmen", "correct": true, "because": "Investitionen nötig"}, {"text": "Weniger Produktivität", "correct": false, "because": "Produktivität steigt"}, {"text": "Geringere Qualität", "correct": false, "because": "Qualität nicht betroffen"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahmen gehören zur Unfallverhütung in einem IT-Betrieb?', 4, '[{"text": "Kabelmanagement", "correct": true, "because": "Verhindert Stolperfallen"}, {"text": "Ergonomische Arbeitsplätze", "correct": true, "because": "Reduziert Haltungsschäden"}, {"text": "Keine Pausenregelung", "correct": false, "because": "Pausen fördern Sicherheit"}, {"text": "Elektrische Sicherheitsprüfungen", "correct": true, "because": "Schützt vor Stromunfällen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet die Unfallverhütung einem IT-Betrieb?', 3, '[{"text": "Weniger Arbeitsunfälle", "correct": true, "because": "Prävention reduziert Risiken"}, {"text": "Erhöhte Produktivität", "correct": true, "because": "Weniger Ausfälle"}, {"text": "Höhere Kosten", "correct": false, "because": "Kein Vorteil"}, {"text": "Bessere Mitarbeitergesundheit", "correct": true, "because": "Unfälle werden vermieden"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Risiken werden durch Unfallverhütung in einem IT-Betrieb minimiert?', 4, '[{"text": "Stolperfallen durch Kabel", "correct": true, "because": "Häufige Gefahr"}, {"text": "Stromschläge bei Hardwarewartung", "correct": true, "because": "Elektrische Risiken"}, {"text": "Geringere Produktivität", "correct": false, "because": "Kein Risiko"}, {"text": "Ergonomische Probleme", "correct": true, "because": "Haltungsschäden vermeidbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche gesetzlichen Grundlagen regeln die Unfallverhütung in einem IT-Betrieb?', 3, '[{"text": "Arbeitsschutzgesetz (ArbSchG)", "correct": true, "because": "Grundlage für Sicherheit"}, {"text": "DGUV-Vorschriften", "correct": true, "because": "Berufsgenossenschaftliche Regeln"}, {"text": "BBiG", "correct": false, "because": "Regelt Ausbildung"}, {"text": "Arbeitsstättenverordnung (ArbStättV)", "correct": true, "because": "Regelt Arbeitsstätten"}]'),
('00000000-0000-0000-0000-000000000000', 'Was unterscheidet die Unfallverhütung eines IT-Betriebs von einem Produktionsbetrieb?', 3, '[{"text": "IT fokussiert Stolperfallen und Stromrisiken", "correct": true, "because": "IT-spezifisch"}, {"text": "Produktion hat mehr Maschinenrisiken", "correct": true, "because": "Physische Gefahren"}, {"text": "IT hat keine ergonomischen Risiken", "correct": false, "because": "Ergonomie relevant"}, {"text": "IT hat spezifische Vorschriften", "correct": true, "because": "Bildschirmarbeit betont"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Unfallverhütung ist im IT-Betrieb gesetzlich vorgeschrieben. b) Unfallverhütung erhöht die Kosten ohne Vorteile.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Gesetzlich ja, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Unfallverhütung reduziert Stolperfallen in einem IT-Betrieb. b) Der Arbeitgeber ist für die Umsetzung verantwortlich.', 3, '[{"text": "Nur a) stimmt", "correct": false, "because": "Beides ist richtig"}, {"text": "Beides stimmt", "correct": true, "because": "Stolperfallen und Arbeitgeberpflicht"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "Beides ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Elektrische Gefahren sind Teil der Unfallverhütung in einem IT-Betrieb. b) Unfallverhütung ist nur im Büro relevant.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Elektrische Gefahren ja, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Unfallverhütung steigert die Produktivität eines IT-Betriebs. b) Kabelmanagement ist keine Maßnahme der Unfallverhütung.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Produktivität ja, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Die DGUV-Vorschriften regeln die Unfallverhütung in einem IT-Betrieb. b) Unfallverhütung hat keine Kosten.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "DGUV ja, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

